	created_at DATETIME(6) NOT NULL,
	updated_at DATETIME(6) NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_reservation_request UNIQUE (user_id, request_key),
	CONSTRAINT ck_reservation_dates CHECK (start_date <= end_date),
	CONSTRAINT ck_guest_count CHECK (guest_count > 0),
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_reservation_calendar ON reservations (status, start_date);

CREATE INDEX ix_reservation_user ON reservations (user_id, status, start_date);

CREATE TABLE calendar_occupancy (
	use_date DATE NOT NULL,
	reservation_id BIGINT,
	block_id BIGINT,
	PRIMARY KEY (use_date),
	CONSTRAINT ck_occupancy_owner CHECK ((reservation_id IS NOT NULL AND block_id IS NULL) OR (reservation_id IS NULL AND block_id IS NOT NULL)),
	FOREIGN KEY(reservation_id) REFERENCES reservations (id),
	FOREIGN KEY(block_id) REFERENCES calendar_blocks (id)
);

CREATE TABLE reservation_history (
	id BIGINT NOT NULL AUTO_INCREMENT,
